#!/usr/bin/env python3
"""
fmp/agents/issue.py
------------------
Structured issue representation for triage agent.

Supports integration with external systems (Crashlytics, etc.) that provide
structured error information.
"""

from __future__ import annotations

from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Literal, Optional


@dataclass
class FileErrorInfo:
    """Error information for a specific file."""
    error_text: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "error_text": self.error_text,
            "metadata": self.metadata,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> FileErrorInfo:
        return cls(
            error_text=data.get("error_text", ""),
            metadata=data.get("metadata", {}),
        )


@dataclass
class Issue:
    """
    Structured issue representation for triage.

    Supports both simple error text and structured file-specific errors.
    """
    failure_type: Literal["build", "test", "crash", "lint", "unknown"] = "unknown"
    error_excerpt: str = ""
    file_errors: Dict[str, FileErrorInfo] = field(default_factory=dict)  # path -> FileErrorInfo
    has_repo_vision: bool = False
    has_probe: bool = False
    retry_count: int = 0
    user_flags: List[str] = field(default_factory=list)
    force_escalate: bool = False
    metadata: Dict[str, Any] = field(default_factory=dict)  # Additional metadata from integrations

    def to_dict(self) -> Dict[str, Any]:
        """Convert to dictionary for JSON serialization."""
        return {
            "failure_type": self.failure_type,
            "error_excerpt": self.error_excerpt,
            "file_errors": {
                path: info.to_dict() for path, info in self.file_errors.items()
            },
            "has_repo_vision": self.has_repo_vision,
            "has_probe": self.has_probe,
            "retry_count": self.retry_count,
            "user_flags": self.user_flags,
            "force_escalate": self.force_escalate,
            "metadata": self.metadata,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> Issue:
        """Create from dictionary."""
        file_errors = {}
        for path, error_data in data.get("file_errors", {}).items():
            file_errors[path] = FileErrorInfo.from_dict(error_data)

        return cls(
            failure_type=data.get("failure_type", "unknown"),
            error_excerpt=data.get("error_excerpt", ""),
            file_errors=file_errors,
            has_repo_vision=data.get("has_repo_vision", False),
            has_probe=data.get("has_probe", False),
            retry_count=data.get("retry_count", 0),
            user_flags=data.get("user_flags", []),
            force_escalate=data.get("force_escalate", False),
            metadata=data.get("metadata", {}),
        )

    def to_peek(self) -> Dict[str, Any]:
        """
        Convert to peek dict format expected by triage_agent.
        Combines error_excerpt with file-specific errors.
        """
        # Combine error_excerpt with file-specific errors
        error_parts = []
        if self.error_excerpt:
            error_parts.append(self.error_excerpt)

        for path, file_error in self.file_errors.items():
            error_parts.append(f"File: {path}\n{file_error.error_text}")

        combined_error = "\n\n".join(error_parts)

        return {
            "failure_type": self.failure_type,
            "error_excerpt": combined_error[:2000],  # Limit to 2000 chars
            "has_repo_vision": self.has_repo_vision,
            "has_probe": self.has_probe,
            "retry_count": self.retry_count,
            "user_flags": self.user_flags,
            "force_escalate": self.force_escalate,
            "file_errors": {
                path: info.to_dict() for path, info in self.file_errors.items()
            },
            "metadata": self.metadata,
        }

    def get_file_paths(self) -> List[str]:
        """Get list of all file paths mentioned in this issue."""
        return list(self.file_errors.keys())
